.map-atlas{--atlas-line:#d4d6d8;--atlas-muted:#555b61;color:#202326;max-width:1320px;margin:0 auto;padding:0 0 2rem;font:14px/1.5 system-ui,sans-serif}
.map-atlas *{box-sizing:border-box}
.map-atlas button,.map-atlas input,.map-atlas select,.map-atlas textarea{font:inherit}
.map-atlas button,.map-atlas a,.atlas-file-button{min-height:36px}
.map-atlas button,.atlas-file-button{background:#fff;border:1px solid #b7bbc0;border-radius:3px;color:#202326;padding:.5rem .8rem;cursor:pointer;white-space:normal}
.map-atlas button:hover,.atlas-file-button:hover{background:#f1f2f3}
.map-atlas button:disabled{cursor:default;opacity:.55}
.map-atlas :is(button,input,select,textarea,a):focus-visible,.atlas-file-button:focus-within{outline:2px solid #222;outline-offset:2px}
.map-atlas a{display:inline-flex;align-items:center;color:#202326;text-underline-offset:3px;padding:.35rem .15rem}
.map-atlas h1{font-size:1.7rem;line-height:1.2;margin:.3rem 0 .6rem;font-weight:650}
.map-atlas h2{font-size:1.2rem;margin:1.3rem 0 1rem;font-weight:650}
.map-atlas h3{font-size:1rem;margin:1.5rem 0 .6rem;font-weight:650}
.map-atlas h4{font-size:.95rem;margin:1rem 0 .5rem}
.atlas-header{display:flex;gap:1rem;justify-content:space-between;align-items:flex-start;padding:1.2rem 0;border-bottom:1px solid var(--atlas-line)}
.atlas-header p{max-width:780px;margin:.35rem 0;color:var(--atlas-muted)}
.atlas-eyebrow{font-size:.65rem!important;letter-spacing:.12em}
.atlas-actions{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem}
.atlas-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.5rem;margin:1.2rem 0}
.atlas-steps button{text-align:left;min-height:44px}
.atlas-steps button[aria-current=step]{border-color:#25282c;background:#e9ebed;font-weight:650}
.atlas-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}
.atlas-field{display:flex;flex-direction:column;gap:.4rem;min-width:0}
.atlas-field>span{font-size:.85rem;font-weight:600}
.atlas-wide{grid-column:1/-1}
.atlas-field input,.atlas-field select,.atlas-field textarea,.atlas-table input[type=number]{border:1px solid #afb4b9;border-radius:3px;min-height:38px;padding:.5rem .6rem;width:100%;background:#fff;color:#202326}
.atlas-field textarea{min-height:86px;resize:vertical}
.atlas-field small,.atlas-note{font-size:.8rem;color:var(--atlas-muted);line-height:1.5}
.atlas-source{border:1px solid var(--atlas-line);border-radius:3px;margin:1rem 0;padding:1rem}
.atlas-source legend{padding:0 .4rem;font-weight:600}
.atlas-source>.atlas-actions{margin-top:.75rem}
.atlas-check{display:flex;align-items:flex-start;gap:.6rem;margin:.35rem 0;cursor:pointer}
.atlas-check input{margin-top:.3rem;accent-color:#303438}
.atlas-check span{min-width:0}
.atlas-table{overflow:auto;max-width:100%;border:1px solid var(--atlas-line);border-radius:3px}
.atlas-table table{border-collapse:collapse;width:100%;font-size:.85rem;text-align:left}
.atlas-table th{background:#f1f2f3;font-size:.75rem;font-weight:650;border-bottom:1px solid var(--atlas-line)}
.atlas-table th,.atlas-table td{padding:.7rem .8rem;vertical-align:top}
.atlas-table td{border-bottom:1px solid #e4e6e8}
.atlas-table tr:last-child td{border-bottom:0}
.atlas-table td small{display:block;font-size:.73rem;color:var(--atlas-muted);margin-top:.25rem;overflow-wrap:anywhere}
.atlas-table td button{margin:.1rem .2rem .3rem 0}
.atlas-table input[type=number]{min-width:110px;max-width:220px}
.atlas-footer{margin-top:1.5rem;padding:1rem 0;border-top:1px solid var(--atlas-line);display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.map-atlas .atlas-primary{background:#292d31;color:#fff;border-color:#292d31;font-weight:600}
.map-atlas .atlas-primary:hover{background:#151719}
.atlas-error{border:1px solid #666;border-left:4px solid #333;border-radius:3px;background:#f4f4f4;padding:.8rem 1rem;margin:1rem 0;white-space:pre-wrap}
.atlas-error[hidden],.atlas-pdf[hidden]{display:none}
.atlas-summary,.atlas-linked{border:1px solid var(--atlas-line);background:#f6f7f8;padding:1rem;margin:1rem 0}
.atlas-summary h3{margin:0}
.atlas-summary p{margin:.5rem 0}
.map-atlas details{border:1px solid var(--atlas-line);border-radius:3px;padding:.7rem 1rem;margin:1rem 0}
.map-atlas summary{cursor:pointer;font-weight:600}
.map-atlas pre{font:12px/1.5 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;background:#f7f8f9;padding:.7rem}
.atlas-file-button{display:inline-flex;align-items:center;position:relative;overflow:hidden}
.atlas-file-button input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}
.atlas-pdf{margin:1rem 0}
.atlas-pdf iframe{width:100%;height:min(76vh,900px);min-height:430px;background:#eee;border:1px solid #888}
.atlas-release>.atlas-actions{margin-bottom:1rem}
[data-atlas-problems]{margin-top:1rem}
[data-atlas-problems] ul{padding-left:1.3rem;font-size:.85rem}
@media(max-width:760px){.atlas-header{display:block}.atlas-header>.atlas-actions{margin-top:1rem}.atlas-grid{grid-template-columns:1fr}.atlas-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.atlas-steps button{font-size:.8rem}.atlas-footer{display:block}.atlas-footer>.atlas-actions+.atlas-actions{margin-top:1rem}.atlas-table th,.atlas-table td{padding:.55rem}.atlas-source{padding:.8rem}}

